def divisibleGame(nums):
    MOD = 10**9 + 7
    n = len(nums)

    # prefix[i] = sum of nums[0 .. i-1], used to get the cost of the elements between two indices
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + nums[i]

    # positions[k] = indices i (increasing) where nums[i] is divisible by k, for k > 1
    positions = {}
    for i in range(n):
        v = nums[i]
        d = 1
        while d * d <= v:
            if v % d == 0:
                if d > 1:
                    positions.setdefault(d, []).append(i)
                other = v // d
                if other != d and other > 1:
                    positions.setdefault(other, []).append(i)
            d += 1

    best_diff = None
    best_k = 2
    for k in positions:
        idx = positions[k]
        # Kadane over the divisible indices only; skipped elements are all non-divisible
        cur = nums[idx[0]]
        top = cur
        for t in range(1, len(idx)):
            a = idx[t - 1]
            b = idx[t]
            # Total value of the non-divisible elements strictly between a and b
            gap = prefix[b] - prefix[a + 1]
            cur = max(nums[b], cur - gap + nums[b])
            if cur > top:
                top = cur
        # Prefer a larger difference, and the smaller k on ties
        if best_diff is None or top > best_diff or (top == best_diff and k < best_k):
            best_diff = top
            best_k = k

    # No k > 1 divides anything: all elements are 1, so Alice takes the smallest element with k = 2
    if best_diff is None:
        smallest = nums[0]
        for v in nums:
            if v < smallest:
                smallest = v
        best_diff = -smallest
        best_k = 2

    return (best_diff * best_k) % MOD
